import type { Id, Level } from "../plan/types";

/**
 * Deterministic ID source for a single command. With a caller-supplied
 * prefix (e.g. a random token generated by the editor) IDs are
 * `${prefix}-${kind}${n}`; without one, `${kind}-${n}` is used. Either way
 * IDs already present in the level are skipped.
 */
export class IdSource {
  private readonly taken: Set<string>;
  private readonly counters = new Map<string, number>();
  readonly created: Id[] = [];

  constructor(
    private readonly prefix: string | undefined,
    level: Level | null,
  ) {
    this.taken = new Set(level ? collectIds(level) : []);
  }

  next(kind: string): Id {
    for (;;) {
      const n = (this.counters.get(kind) ?? 0) + 1;
      this.counters.set(kind, n);
      const id = this.prefix ? `${this.prefix}-${kind}${n}` : `${kind}-${n}`;
      if (!this.taken.has(id)) {
        this.taken.add(id);
        this.created.push(id);
        return id;
      }
    }
  }

  isTaken(id: Id): boolean {
    return this.taken.has(id);
  }

  reserve(id: Id): void {
    this.taken.add(id);
    this.created.push(id);
  }
}

export function collectIds(level: Level): string[] {
  return [
    level.id,
    ...Object.keys(level.vertices),
    ...Object.keys(level.walls),
    ...Object.keys(level.openings),
    ...Object.keys(level.rooms),
    ...Object.keys(level.furniture ?? {}),
  ];
}
